using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class JózefIgnacyKraszewski
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Obcy ludzie zdumiewają się pytając, jaka to jest ta Rzeczpospolita nasza, w której zbrodzień podobny bezkarnie chodzić może długie lata, z wyrokiem nad głową, którego nikt nie śmie spełnić ino dlatego, że do rodziny możnej i znacznej należy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Rzadka to rzecz, aby mały człowiek poszanował w upadku niegdyś potężniejszego od siebie. Jest coś niepoczciwego w naturze ludzkiej, że taki biedny człek niemal czuje się zwycięzcą, gdy los mu da w ręce takiego, który nad nim górował.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "My mamy z przeszłością do walczenia i z nałogami wielą. Można by słownik ułożyć z tych wyrazów, do których się u nas fałszywe przyczepiły pojęcia. Mamy do czynienia z dykcjonarzem. Począwszy od naszej wolności, wszystko w nim przerobić potrzeba.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "A obyczaj stary! Tym się też nie godzi pomiatać. Jak zaczniemy wszystkim pomiatać, jak zaczniemy wszystko przerabiać, nic nie zostanie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Przez gorsze idzie się do lepszego, a dróg ludzkich sędzią jest Ten, co je wyznacza.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jak z potwarzy zawsze coś zostanie, tak i ze zgorszenia część żądła się wpija.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nic lepiej nie probuje upadku człowieka i narodu nad upodobanie w grze.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Starzeje ten tylko, kto sobie zestarzeć dozwala.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kobieta z rozumem odgaduje wszystko… a ta, co go nie ma, nabrać go nie potrafi…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Świata blaskiem pożyczanego dostatku nigdy oszukać nie można, a godnie noszone ubóstwo każdy szanuje.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nic lepiej nie maluje fatalizmu, w który popadliśmy przez lenistwo umysłowe i wszelakie inne, nad to wiekuiste: – Jakoś to będzie. – Jak będzie i kiedy i przez kogo, nie wiemy, ale nas pociesza, że jakoś to będzie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Z iluż to szaleństw rodzą się arcydzieła, a proszę mi pokazać, aby jedno rozum wystrugał??", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Słowo jest czymś więcej niż serce, bo serca ja nie jestem panią, a słowu memu jam królową.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "To tylko prawdziwie piękne, co po latach wielu jeszcze się tak jak pierwszego dnia wydaje.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzi wdzięcznych znajdzie się coś może, narody zawsze niewdzięczne być muszą!", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Smutek na człowieku jest jak piasek na mogile, kogo on przysypie, niełatwo odkopać.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Im dłużej karmim w sobie jakie uczucie, przekonanie, pojęcie, tym ciężej się z nim rozstać i długo człowiek oczywistości nawet się opiera, z prawdą walczy, fałszem żyć woli, niż wyrzec się tego, co już część jego istoty stanowi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kochać tych, co zasługują na to, aby byli kochani, bardzo łatwo; ale miłość mieć dla upadłych i nie porzucić ich, gdy wszystko opuściło, chrześcijańskim jest dziełem.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Myślisz, że stracona wiara odzyskuje się rozumem? Nie. Jak poszła, tak powraca przez serce.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "W temperaturze człowieka widzimy ten sam fenomen, co na ziemi, gdy w jednym półsferzu podnosi się ciepło, na drugim panują chłody – prawie zawsze serce ostygłe idzie z płonącą fantazją i rozbujałą głową.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Z dobrą nowiną do poczciwego człowieka nigdy za wcześnie przyjść nie można.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Dowiedziona rzecz, że ci co sobą rządzić nie umieją, najlepiej drugimi potrafią…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Dziś wszystko się pragnie uszlachetnić – szewc zowie się artystą obuwia… krawiec mówi ci o moralnym znaczeniu swych płodów, traktiernia zowie się „akademią gastronomiczną”, czemuż by jatka nie miała się nazywać „instytutem mięsnym”?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Od dzisiaj wszystko się pragnie uszlachetnić; szewc nazywa się artystą obuwia; krawiec mówi o moralnym znaczeniu swoich płodów; traktierna nazywa się „akademią gastronomiczną”; czemuż by jatka nie miała się nazywać „instytutem mięsnym”?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Dziwna w tym ludzka natura, która z pokrewieństwa naszego z małpami wynikać musi, jak się zdaje, że zawsze pragniemy zastosować się do tego, co nas otacza i przebrać się za kogo innego.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Odzienie to jest taka rzecz, co jak tytuł książki naprzód każdemu w oczy wpada.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Od kobiety, która pragnie zatrzymać, uciec jest niepodobieństwem.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Świat nie ma zwyczaju gonić tych, co się od niego odwracają z pogardą, jemu trzeba sideł, lepu, a wziąć go można bardzo łatwo.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Świat popsuty! Żadnej w nim pasji, żadnej, co się nazywa – chodzą bladzi jak ćmy po świecie, a patrząc na nich aż spać się chce i poziewać.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Im kto więcej w życiu cierpiał, tym więcej przecierpieć może.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Im prostsze były wyroby kraju, tym większa obcych potrzeba. Kupcy zyskiwali najwięcej na sprzedaży tu właśnie, gdzie to, co przywieźli, osobliwym było i pożądanym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miał tę pańską ogładę, która niewiastom jest miłą, bo wyższość jakąś obiecuje, choć najczęściej jest łupiną gładką pustego orzecha.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Na zoranej pługiem żelaznym ziemi, choć ją zielone trawy i kwiaty okryją, zostają blizny na zawsze.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Swawola zawsze więcej jedna przyjaciół niż surowość i karność.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Słowo wiatr… ci co mówią wiele, zazwyczaj czynią mało.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Z ludzi jak z kwiatów woń wychodząca na świat, niekoniecznie odpowiada temu, co się w nich w istocie znajduje. Pachnie często trucizna, odraża wonią dobroczynne ziele. Tak i sława ludzka nie pełna bywa i niesprawiedliwa, podnosi często to, co na to nie zasługuje, zapomina o tem, co najbardziej pamięci warto.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzie się nigdy nie cisną ku mogiłom, zwracają się ku życiu, a jeżeli ich obowiązek napędzi ku nim, nie trwają długo.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wszystko, co przychodzi niespodzianie – spada jak gromem na człowieka i na czas jakiś pozbawia go siły.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma niebezpieczniejszej rzeczy dla człowieka, dla ludzi nad pomyślność. W przeciwnościach potęgują się siły, uchodzą w szczęściu. Zawraca się głowa, przychodzi upojenie, mięknie serce, niknie energia, baczność się traci.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Zakon można znękać, ale go zabić nie potrafi nikt. Odrodziłby się w innej sukni, z innym znakiem, pod innym hasłem… z tym samym duchem. Zakon jest nieśmiertelny. My możemy paść wszyscy, on – nigdy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Pozytywizm obrał nas z ducha, zniżył poziom myśli będących w obiegu, uczynił rozsądnymi do zbytku, ale istotami bez polotu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Dziś niemal wszyscy są do siebie podobni i pretendenta do tronu hiszpańskiego nader trudno od porządnego szewca odróżnić.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kobieta najostyglejsza znajduje przyjemność odgrzewając się przy młodym takim ognisku.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kobiety noszą się z talentami, póki za mąż nie pójdą, potem na uprawę ich nie mają czasu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kto raz doświadczył, że własną wolą rządzić się nie umie, ten powinien ze świadomością słabości własnej wolę swą poddać innej, wyższej i wykształceńszej.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzie, ile razy spotkają się z podobną bezczelną zuchwałością, najczęściej przed nią głowę skłaniają.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Na świecie wiara w siebie i umiejętność sprzedania się należą do najgłówniejszych tajemnic tego, co się szczęściem nazywa. Kto sam siebie nie ceni i nie chwali, tego ludzie z pewnością, wyjąwszy chyba malutką garstkę, ani oszacują, ani podniosą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nieszczęściem zwalani ludzie i rękawiczki zarówno trudno oczyścić się dają.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Spekulować dobrze można tylko na dwóch rzeczach: na tym, co łechce miłość własną, i co brzuch wypełnia, a podniebieniu pochlebia.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "W hotelu uczy się najlepiej filozofii praktycznej.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wiadomo, że sławę rozumu zyskuje się najłatwiej, gdy się cudzy podziwia.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wszystko złe zawsze należy przewidywać, a dobremu nie dowierzać – to moja zasada.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Żaden wyżeł kuropatw tak nie zwęszy, jak ludzie pieniądze. Kto ich nie ma, niech się dmie jak chce – czci mu nie oddadzą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nas ręka boża dotknęła za to, żeśmy własnych panów szanować nie umieli, za to dziś czerń nam karki gniecie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Rosło to złe ziele jak pokrzywa pod płotem, która gdy się z ziemi wytyka, ani jej widać, nie wiadomo kiedy do góry się bierze, aż i płot sam zakrywa.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Złym Bóg dopuszcza godzinę zwycięstwa, ale im panowania nie daje.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "A jestli to z pożytkiem dla człowieka, gdy zawczasu zna przyszłość swoją? Gdyby Opatrzność widziała z tego korzyść i potrzebę dla nas, czyżby nas władzą tą nie obdarzyła?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wiek tak samo na twarzach sędziwych nieznaczne brodawki i znamiona powiększa, jak w duszy wady człowieka. Nad starością czuwać trzeba i ona nad sobą czuwać powinna.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wielka piękność niewiastę rychlej psuje, niż lepszą czyni. Robi ją dumną, płochą często, a w kadzidłach się miłującą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Interes nie miał dla niego strony moralnej, ale był zadaniem, którego wartość stanowiło przezwyciężenie trudności.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzie nawykli do mentorowania drugim niełatwo znoszą, gdy im kto omyłkę w rachubie wytknie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Najśmieszniejszym ze wszystkich urojeń ludzkich jest marzenie o nieśmiertelności na ziemi. Rody, imiona, ludzie, wszystko maleje, umiera i rozkłada się, służąc za materiał nowym wielkościom i nowym blaskom.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nikt łatwiej się nie obraża nad tego, który niezupełnie sam z siebie jest zadowolonym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Zawsze kochać się można i trzeba. To czas bardzo przyjemnie skraca, nikomu nie szkodzi i wielce jest nauczającym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Biada mężczyznom, co płaczą! Łza męska ze krwią chyba na ofiarę wielką płynąć powinna, nigdy na obmycie powszednich bólów żywota; jest ona skarbem, którym szafować się nie godzi. Kobieta nią żyje, mężczyzna nią umierać chyba powinien.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Dziwna rzecz, że w człowieku naprzód się wyszlachetnia oblicze, naprzód wypiękniają rysy twarzy, a na ostatku ręka.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Namiętność czyni okrutnymi ludzi nawet najlepszych.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kto może żyć kawałkiem chleba, być zdrowym i silnym, nie tęsknić za delikatesami – stokroć jest większym panem niż milionowy sybaryta, co się lęka więcej o utratę dobrego stołu niż dobrego imienia.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Najczęściej, o co się człowiek najmocniej stara, czego najgoręcej pragnie, na złe mu wychodzi, czego się lękał, zbawić może.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nauka ma to do siebie, że, by się w człowieku mocno usadowiła, potrzebuje czasu. Co prędko się nabywa, ulatuje też żywo i później ślad nie pozostaje ciężkiej pracy i tych podwalin gruntownych, które budowę dźwigać powinny.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "U panów miłość wchodzi przez głowę i często do piersi trafić nie może, a szukając serca, znajduje pustkę.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "W pałacu radzi ci są, bo się nudzą, ale oni z ludźmi nie swego świata żyją tylko z nudów i przez grzeczność… a szczerej dla nich miłości nie mają, bo ich za pośledni rodzaj ludzi nawykli rachować…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Gdy mi kto kadzi, zawsze się boję, by gdzieś niedaleko smrodu nie było.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kto uchodzi, ma sto dróg; kto gna, jedną.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma nic gorszego jak z chłopa pan, a z brata nieprzyjaciel.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Pracowitym dzień się poczynał – próżniakom nie skończył się jeszcze.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Starzenie się ludzi podlega zaprawdę prawom dziwnym. To co w twarzy stanowiło jej piętno charakterystyczne, jej właściwość, z wiekiem nie ginie, ale się uwydatnia.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Człowiek jest jak zegarek, który im więcej się naprawia, tym gorzej idzie – to dowiedziona rzecz. Ja mam zwyczaj, gdy mi się psuje zegarek, darowywać przyjacielowi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma w świecie zaciętszych wrogów nad tych, którzy potrzebują uniewinnić się ze zmiany uczuć dla dawnych przyjaciół.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ty sam się zewsząd czynisz wygnańcem, jesteś z tego rodzaju ludzi, po których plecach wszyscy się wspinają i którzy stworzeni są na drabiny.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Każda epoka ma swe wymagania; nasza zdaje się mieć za zadanie wszystkie stany i klasy pomieszać ze sobą, wszystko bezładnie zniwelować, wszystkie prawa nabyte zniszczyć, wszelkiej powadze zaprzeczyć, wszystkie tradycje odepchnąć.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Twarz jego, jak moneta kosmopolityczna, nie miała stempla pochodzenia.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Znać słabości ludzkie, aby z nich korzystać, swoje własne, aby się ich obawiać – to rozum cały. Reszta to romanse, które bawią, a nie tuczą…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Godziny szczęśliwe rzadkie są w życiu ludzi, rzadsze w narodów życiu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kto nie wie i nie czuje, co mu przeznaczono, ten jak martwa kłoda płynie z wodą. Człowiek od kolebki musi znać dolę swoją i sam jej pomagać.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość nie jestże prawie zawsze ubóstwieniem i bałwochwalstwem z jednej strony, a chłodnym przyjmowaniem z drugiej?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Niewieście usta zamknąć trudniej niż mężczyźnie zemsty zabronić.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Prawdą to jest, że małe ciosy wywołują skargi i jęki, a srogi raz milczeniem się zamyka.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Małżeństwo to przecie ostatnia loteria, jak się na nim stawkę przegra, pozostaje tylko modlić się do św. Józefa, patrona dobrej śmierci.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Możeż być co nudniejszego nad ucztę podobną, ceremonialne jedzenie z obowiązkową rozmową, wśród których ceremonia zawadza jedzeniu, jadło przeszkadza rozmowie, i nie wie się najczęściej ni co się jadło, ani jakie się powiedziało niedorzeczności?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Tylko ubogich grzechy nie są przebaczone; majętni na złotych szatach bezkarnie plamy noszą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Charaktery są logiczne zawsze. Kto umie kochać, kocha, kto jest złym, musi nim być do końca.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Są uczucia i myśli, które zasłaniać musi człowiek, boby i sam na nie patrzeć nierad.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Trzeba umieć zapomnieć jutra, aby żyć dniem dzisiejszym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ci, co się zapinają mocno, najczęściej bieliznę mają brudną lub żadnej.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Humor ma swoje prawa, najprzód wydrapuje się na pewną wyżynę pozorną, z której wygodnie jest sarkać, nie dając się pochwycić, po wtóre posługuje się fantazją dozwalającą omijać miejsca, których się przebrnąć nie spodziewa, na ostatek chwyta on, co napadnie, i sieka na bigos najkosztowniejsze ingrediencje z najbrudniejszym śmieciem, i to mu uchodzi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Każdy wiek tworzy sobie fizjognomie sobie właściwe. Niegdyś, mimo walk, niepokojów i twardych prób losu, wielki spokój ducha i męstwo piętnowały się majestatyczną na licu pogodą. (…) Na dzisiejszych twarzach wypieszczonych dzieci wieku widać konwulsje jego, chorobę, słabość, niecierpliwość. Twarze są potargane, niespokojne, wystraszone, gniewne, wyzywające, nieszczęśliwe.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma niebezpieczniejszych apostołów nad kobiety. W ich ustach prawda nabiera blasku, a fałsz traci swą potworność. Kunszt uwodzenia nawet bez świadomości jest im wrodzonym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wszyscy Francuzi przesadzają (…) dlatego, że prawdziwego uczucia im braknie. Kochacie głowami i zmysłami, nie sercem, dlatego zmagacie się na czułości, nie wiedząc miary ich i wagi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Może to wydać się paradoksem, lecz jest prawdą, że jak miłość i nienawiść, tak duma i pokora zlewają się czasem w nierozwikłanego coś i niezrozumiałego.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "O tym jestem przekonana, że idąc prostą drogą pokonywa się najłatwiej tych, co idą krzywymi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Chłop poleski, mimo codziennych przykładów niewiary żon i córek wstydu, drażliwy jest na to; nie mogąc mścić się na panu, będzie się mścił na żonie; a bieda nawet i panu, jeśli go do ostateczności przywiedzie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jest to niezaprzeczona prawda: wpływ dziennego światła modyfikuje nawet uczucia i myśli, dorzucając do nich wstyd. Człowiek sam przed sobą nagość swą chcąc ukryć, szuka figowego liścia; tym liściem są myśli, którymi inne, nagie przykrywa do nocy. Światło uczucia hamuje, myśli krępuje wstydem pierworodnym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Karczma to serce wsi, tak jak cerkiew jej głową, a żołądkiem jej dwór; ręce i nogi tego ciała to chaty wieśniacze.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Tamto pańskie kochanie bardzo jakieś piękne, trochę smutne, a choć smutne, to miłe. I kończy się, mówią, zawsze niewesoło.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Wszystko złe, jakie kiedy książki przewracając głowę zrobić mogły, na nim zrobiły.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Życie to smutne, a jednak nawyknieniem lekkie, byleby Bóg rodził, byleby ich zbyt obfity połów ryb głodem nie straszył, bo wierzą w przysłowie: Kiedy się ryba łowi, żyto się nie rodzi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kto nie umie być ciekawym, ten szczęśliwym być nie może. Ciekawość jest pierwszym stopniem do szczęścia, nie do piekła. Kto nie ciekawy, żyć niewart.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "To rzetelna prawda, iż tylko po rękach można poznać człowieka dobrze urodzonego. Widzisz, asindziej, gdy trzy, cztery, pięć pokoleń nic rękami nie robiło, zdrobniały one i wydelikaciły się, to naturalna. W drugim pokoleniu u dorobkiewiczów jeszcze łapy. Twarz będzie czasem piękna, arystokratyczna, rysy już się wygładzą, a ręce zostają długo na pamiątkę tym rodom, które nimi na życie pracowały.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "A ostatecznie synowi pozostawił król w spuściźnie najstraszniejszą anarchią, coś na kształt domu, w którym stary naruszywszy porządek, nowego zaprowadzić nie umiano.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Królowanie u nas nie czym innym jest, ino męczeństwem. Na potwarze, nienawiści, rokosze, na pracę i czuwanie dniem i nocą musi być zbrojnym. Rycerzem być u nas nieochybnie być potrzeba, bo wojny stoją dokoła, ale zarazem statystą i politykiem, a nade wszystko mężem wielkiego sumienia i ofiarności bez granic.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ówczesna Polska rozpadła się na dwa wielkie obozy. Gdzie tylko cywilizacja zachodnia z ogładą i pogardą obyczaju starego się wcisnęła, tam moralność była zachwianą i nadwerężoną; gdzie surowe, stare panowało prawo, ludzie z żelaznym stoicyzmem opierali się zepsuciu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Uczciwi są to ludzie spokojni, którzy nieradzi krzyczeć i podnosić wrzawę, a szyby w oknach wybijać. Mniejszości burzliwe wszędzie górą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Zaraza się pochwyca łatwo.(…) Im z większej wysokości płynie, tym niebezpieczniejsza jest.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Już to pewna, że kto całe życie pracuje nad jednym, lżej mu idzie, ręka się wprawia, ale umysł ociężeć musi, mechanicznie palce wykonywają, czego się wyuczyły, a głowa pracować nie potrzebuje. Jest w tym zło, jest i dobro. Może ten dobroczynny podział pracy nadaje się dla mas, które nie mają wielkich darów – ale na ludzi, co by chcieli iść naprzód, nakłada kajdany.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość, nawet macierzyńska, ma te niewytłumaczalne słabości, w których nad sercem zapanować rozum nie może… A serce matki jest najpotężniejszym z serc na ziemi i miłość matki jest jedyną, której nic osłabić nie może.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Mówiłem tobie ze sto razy, rozum siedzi w chlebie z solą i cebulą, a nie w pieczonej gęsi, bądź oszczędny i skromny i nie łżyj przed światem.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Testament to dobra rzecz, dobra rzecz. Nie orzesz, nie siejesz, zadzwonili po nieboszczyku i wdziewasz jego pot, głód, grzechy lub cnoty, ani Bóg zapłać nie powiedziawszy. O! testament to ładna rzecz.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Najniebezpieczniej jest do improwizacji się gotować i do pojedynku na słowa czy na szpady z góry pchnięcie obmyśleć. Ironia losu zawsze prawie potem inaczej stawi nieprzyjaciela i wielkie przygotowania wniwecz obraca.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma gorszych szpiegów nad próżniaków. Tam gdzie jest ich wiele, najmniejszy wypadek nie przechodzi bez ogromnego rozgłosu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Od niepamiętnych czasów miłość nie może się obyć bez powiernika, tak jak sztuka mięsa biała bez chrzanu czy musztardy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jest to pierwszym znamieniem wyższości człowieka, gdy ma instynkt oszacowania ludzi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ma to do siebie czysty umysł i jasne serce, że z nimi wkrótce czuje się człowiek bratersko oswojonym i pociągniętym ich siłą. Ludzie fałszu odpychają tylko i niepokoją, nawet największą sztuką nie mogą obudzić zaufania, a gdy je pozyskają, zostaje zawsze w człowieku obawa niewytłumaczona, która jest przestrogą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Potwarz jest jak błoto, choćby na niewinnego padła, ślad po niej przetrwa.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Prawdę rzekłszy, nigdy nie pięknym nie był, ale chwilami udawało mu się być okropnym.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Są ludzie, których dola w szczególniejszy doświadcza sposób. (…) Słabym życie uchodzi spokojniej. Silniejsi są do walk stworzeni, nie oszczędza im też bojów przeznaczenie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Serce czasem przeczuwa, rozum w dochodzeniu przyszłości jest zawsze zawodnym; bo serce ma instynkt nieochybny, siłę jakąś mistyczną, której rozsądek się wyrzekł.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Aby mieć wyobrażenie o nikczemności człowieka, potrzeba w nieszczęściu tylko żądać pomocy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Bóg wiele przebacza, ludzie nigdy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Chcesz się żenić? Winszuję, ale nie zazdroszczę.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Człowiek pragnie w miłości tego, czego mu najwięcej braknie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Gnuśność poniewiera tysiące ludzi, praca nie zabija nikogo.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jak dwie perełki w oceanie życia,\nJak dwie gwiazdeczki na niebie,\nŚwiecą nam do powicia\nDwa słowa – kocham ciebie.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jakże dziwne jest serce ludzkie! Gdy nie ma kogo kochać, tęskni; gdy długo jedną rzecz kocha, tęskni; gdy się z kochaną istotą rozstanie, znowu tęskni.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Jest jedna miłość, która nie liczy na wzajemność, nie szczędzi ofiar, płacze a przebacza, odepchnięta wraca – to miłość macierzyńska.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Każda z kobiet prawie inaczej się kochać każe.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Kochać trzeba bliźniego, ale mu pobłażać się nie godzi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Komu pilno do bitwy, ten często pierwszy z niej ucieka.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Któż nie zna jednego rodzaju ludzi, przez któren najbliżej pokrewni jesteśmy z małpami? To stworzenie ma twarz podobną do ludzkiej, głos człowieka, uśmiech głupi w ustach, i kawał gąbki w miejscu mózgu; ma wszystko człowiecze prócz woli; – wola jego jest wolą naśladowania. Stąd można podobnych nazywać człowieko-małpą…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Leniwi zawsze wiedzą, która godzina.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzie boją się zmian, nawet na lepsze…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ludzie zawsze są niewdzięczni, a sami będąc winni, grzech swój na cudze radzi zwalają barki…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Mało ludzi z miłości umiera, a tak wiele z niej żyje!", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Łatwiej było złego obalić niż na lepszego się zgodzić", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Mamy może prawo nie zbierać i nie zapracowywać, jak się komu podoba, ale tracić nie mamy prawa; kto traci, winien jest wobec społeczeństwa, rodziny, przeszłości i przyszłości.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Między koniem a kobietą jest wiele podobieństwa: oboje kochamy, obojgu nie wierzymy, bez obojga się nie obejdziemy.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość jest poetycznym złudzeniem, które żeby długo zatrzymać, nie trzeba dotykać palcami jak bańki z mydła, bo zmienia się w kroplę brudnej wody.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość nie jestże zawsze prawie ubóstwieniem i bałwochwalstwem z jednej strony, a chłodnem przyjmowaniem z drugiej?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość pozyskana wkłada wielkie i święte obowiązki.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Miłość uczciwa jest jak smarowidło w wozie, jużcić i bez niego jechać można, ale lżej z nim i nie skrzypi.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Młode uczucia są najwłaściwsze młodemu wiekowi, ale nie wyłącznie mu należą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Naśladowania wszelkie niewiele warte, w literaturze rodzą lichoty, w polityce – potwory.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie jestże to wielka i piękna rzecz, nie będąc niczym, być wyższym nad wszystko i niczego się nie lękać?", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie każdy i nie zawsze zapłakać może.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma miłości, gdzie są tajemnice.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Nie ma smutniejszego widoku nad walkę z sobą człowieka, który czuje, że z niej nie wyjdzie zwycięzcą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Panowie mają ten przywilej, że się zawsze pięknie wydają nawet w oczach tych, co im zazdroszczą.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Piękne kobiety nie mają przyjaciółek, ale za to tylu przyjaciół…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Praca tylko może dać skrzydła natchnieniu.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Przysiąc, że się będzie kochało, jest to przysięgać po pijanemu, że się nigdy nie wytrzeźwieje, a wytrzeźwienie, nie pytając człowieka, samo przychodzi z ustaniem przyczyny.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Serca kobiet, jak aniołów, pełne są miłości i litości.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Spowiadacie się raz w rok, a grzeszycie co godzina; fundujecie klasztory, budujecie kościoły, więcej dla oka ludzkiego niż dla chwały bożej; sypiecie jałmużny, aby jęki ubogich waszego snu błogiego nie przerywały; całujecie po rękach księży, aby wam broić dozwalali i nie karcili… Ano! Możeście i synami kościoła, ale czyście synami Bożymi – nie wiem.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Tylko zacni ludzie zdolni są do prawdziwej miłości; źli zaczynają od rozpusty i kończą na niej.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ubogi, który żeni się z bogatą, kładzie sobie stryczek na szyję i oddaje drugi koniec w ręce żony.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Ubóstwo jest jak trąd, który łatwo przylega, a wyleczyć się z niego trudno.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Umysł nadto jest płaski, aby mógł pojąć myśl tak głęboką, lecz to wcale jej doskonałości nie ubliża, iż jej zrozumieć nie można.", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "W podróży i w życiu niecierpliwość rośnie w miarę, jak się zbliżamy do celu…", Author = "Józef Ignacy Kraszewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Józef_Ignacy_Kraszewski", Text = "Z wielu względów jesteśmy ogólnie biorąc najobficiej od Boga udarowani; nie brak nam ani talentów, ani pomysłu, ani szlachetności, ani gotowości do ofiar; jednej woli wyrobić w sobie nie umiemy.", Author = "Józef Ignacy Kraszewski" },
        };
    }
}